// gm_counter: your first typeshi program. lock in fn.
// `typeshi build` turns this into lib.rs, right next to it. don't edit lib.rs. nobody can edit it.

gm!("7PxhmDuhhe394QJgKyW1P7Ce4dPCfFPN2yKq4KCCj7Vj");

stealth_launch gm_counter {
    /// one counter. counts gms, farms aura.
    frame Counter {
        cabal: Pubkey,
        gms: u64,
        aura: u64,
    }

    cap_table Launch {
        #[account(rent_free, payer = exit_liquidity, space = 8 + Counter::INIT_SPACE, seeds = [b"counter"], bump)]
        counter: Account<Counter>,
        exit_liquidity,
        system_program,
    }

    cap_table Gm {
        #[account(mut, seeds = [b"counter"], bump)]
        counter: Account<Counter>,
        anon,
    }

    /// make the counter. whoever launches it is the cabal.
    lock_in fn launch(ctx) -> W {
        mark_to_market!(counter.cabal = per_my_last_email!(exit_liquidity).key());
        probably_nothing!("gm. we're live.");
        were_so_back!()
    }

    /// say gm. number go up.
    lock_in fn gm(ctx) -> W {
        number_go_up!(counter.gms);
        aura_farm!(counter.aura, 10);
        were_so_back!()
    }
}

// print_feed.shi: a tiny Tickerz print feed, written in typeshi.
// everything gets a ticker.

gm!("7PxhmDuhhe394QJgKyW1P7Ce4dPCfFPN2yKq4KCCj7Vj");

stealth_launch print_feed {
    /// eight bytes of ticker, e.g. b"CPI\0\0\0\0\0".
    type_shi Ticker = [u8; 8];

    /// the biggest value a print can carry: 1,000,000 bps (10,000%).
    #[on_god]
    const MAX_PRINT: Bps = 1_000_000;

    /// one feed per ticker. counts its prints, farms aura.
    frame Feed {
        ticker: Ticker,
        cabal: Pubkey,
        prints: u64,
        aura: u64,
    }

    /// one print. written once, at init. nobody can edit it.
    #[on_god]
    frame PrintRecord {
        feed: Pubkey,
        seq: u64,
        value: Bps,
        printed_by: Pubkey,
        printed_at: i64,
    }

    /// leaked to every indexer watching. probably nothing.
    alpha_leak Printed {
        ticker: Ticker,
        seq: u64,
        value: Bps,
        pretty: String,
    }

    #[instruction(ticker: Ticker)]
    cap_table ListTicker {
        #[account(rent_free, payer = exit_liquidity, space = 8 + Feed::INIT_SPACE,
                  seeds = [b"feed", ticker.as_ref()], bump)]
        feed: Account<Feed>,
        exit_liquidity,
        system_program,
    }

    cap_table Print {
        #[account(mut, has_one = cabal, seeds = [b"feed", feed.ticker.as_ref()], bump)]
        feed: Account<Feed>,
        #[account(rent_free, payer = exit_liquidity, space = 8 + PrintRecord::INIT_SPACE,
                  seeds = [b"print", feed.key().as_ref(), &feed.prints.to_le_bytes()], bump)]
        print: Account<PrintRecord>,
        cabal,
        exit_liquidity,
        system_program,
    }

    cap_table Gm {
        feed: Account<Feed>,
    }

    /// list a ticker. whoever lists it is the cabal.
    lock_in fn list_ticker(ctx, ticker: Ticker) -> W {
        trust_me_bro!(ticker[0] != 0, "a ticker needs a name. skill issue.");
        mark_to_market!(feed.ticker = ticker);
        mark_to_market!(feed.cabal = per_my_last_email!(exit_liquidity).key());
        probably_nothing!("gm. new ticker listed.");
        were_so_back!()
    }

    /// print a value. it lives on-chain forever.
    #[tokenmaxx]
    lock_in fn print(ctx, value: Bps) -> W {
        trust_me_bro!(value mogs 0, "a print of zero is not a print.");
        funds_are_safu!(value <= MAX_PRINT);
        let seq = per_my_last_email!(feed.prints);
        let feed_key = per_my_last_email!(feed).key();
        mark_to_market!(print.feed = feed_key);
        mark_to_market!(print.seq = seq);
        mark_to_market!(print.value = value);
        mark_to_market!(print.printed_by = per_my_last_email!(cabal).key());
        mark_to_market!(print.printed_at = Clock::get()?.unix_timestamp);
        number_go_up!(feed.prints);
        aura_farm!(feed.aura, 10);
        probably_nothing!("print #{} locked in", seq); // #[tokenmaxx] strips this log. CU is CU.
        probably_nothing!(Printed {
            ticker: per_my_last_email!(feed.ticker),
            seq,
            value,
            pretty: looksmaxx!(value),
        });
        were_so_back!()
    }

    /// say gm. it only reads, so it's an `ape fn`, not a `lock_in fn`.
    ape fn gm(ctx) -> W {
        let prints = per_my_last_email!(feed.prints);
        bull prints mogs 0 {
            probably_nothing!("gm. {} prints. nobody can edit them. wen moon? {}", looksmaxx!(prints), wen_moon());
        } bear {
            airdrop!();
        }
        were_so_back!()
    }

    /// there is no edit instruction. this fn exists to tell you why.
    few_understand fn edit(_print: &PrintRecord, _value: Bps) -> W {
        L("nobody can edit it. skill issue.")
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        fn a_print() -> PrintRecord {
            PrintRecord { feed: Pubkey::default(), seq: 0, value: 425, printed_by: Pubkey::default(), printed_at: 0 }
        }

        #[test]
        fn nobody_can_edit_it() {
            assert!(edit(&a_print(), 9_000).is_err());
        }

        #[test]
        fn looksmaxxed() {
            assert_eq!(looksmaxx!(425u64), "425");
            assert_eq!(looksmaxx!(1_234_567u64), "1.23M");
        }

        #[test]
        fn wen_moon_is_soon() {
            assert_eq!(wen_moon(), "soon\u{2122}");
        }

        #[test]
        fn error_codes_are_tradition() {
            assert_eq!(u32::from(Cope::SkillIssue), 1);
            assert_eq!(u32::from(Cope::WifeChangingMoneyNotFound), 6);
        }
    }
}

// degen_desk.shi: every typeshi keyword in one program, so the compiler checks all of them.
// it is a toy. do not run a desk on it. obviously.

gm!("7nTB3oS3PmJn5JkDppPbnESpm59zdbBCDPmi53djce6P");

// the panic handler. build with `--features custom-panic` to turn it on.
this_is_fine!();

stealth_launch degen_desk {
    cope {
        DeskClosed = "desk is closed. touch grass.",
    }

    /// 2.5% carry, as is tradition.
    deadass FEE_BPS: Bps = 250;

    frame Desk {
        cabal: Pubkey,
        frens: [Pubkey; 4],
        locked: bool,
        version: u8,
        opens_at: i64,
        closes_at: i64,
        last_price: u64,
        ath: u64,
        floor: u64,
    }

    frame Bag {
        owner: Pubkey,
        points: u64,
    }

    cap_table OpenDesk {
        #[account(rent_free, payer = exit_liquidity, space = 8 + Desk::INIT_SPACE, seeds = [b"desk"], bump)]
        desk: Account<Desk>,
        exit_liquidity,
        system_program,
    }

    cap_table Trade {
        #[account(mut, has_one = cabal)]
        desk: Account<Desk>,
        cabal,
        ser,
        kol,
        system_program,
    }

    cap_table Brrr {
        #[account(has_one = cabal)]
        desk: Account<Desk>,
        #[account(mut)]
        mint: Account<anchor_spl::token::Mint>,
        #[account(mut)]
        bag: Account<anchor_spl::token::TokenAccount>,
        #[account(mut)]
        vc: Account<anchor_spl::token::TokenAccount>,
        cabal,
        token_program,
    }

    cap_table Grow {
        #[account(mut, has_one = cabal, graduate = 8 + Desk::INIT_SPACE + 64)]
        desk: Account<Desk>,
        cabal,
        exit_liquidity,
        system_program,
    }

    cap_table FireEveryone {
        #[account(mut, has_one = cabal)]
        desk: Account<Desk>,
        #[account(mut)]
        bag_a: Account<Bag>,
        #[account(mut)]
        bag_b: Account<Bag>,
        #[account(mut)]
        cabal,
    }

    cap_table Liquidate {
        #[account(has_one = cabal)]
        desk: Account<Desk>,
        #[account(mut)]
        bag: Account<Bag>,
        #[account(mut)]
        cabal,
    }

    cap_table Retire {
        #[account(mut, has_one = cabal, golden_parachute = cabal)]
        desk: Account<Desk>,
        #[account(mut)]
        cabal,
    }

    cap_table CheckBags {
        desk: Account<Desk>,
        anon,
    }

    lock_in fn open_desk(ctx, opens_at: i64, closes_at: i64) -> W {
        margin_call!(closes_at <= opens_at, "the desk closes before it opens. skill issue.");
        let me = per_my_last_email!(exit_liquidity).key();
        mark_to_market!(desk.cabal = me);
        mark_to_market!(desk.frens = [me; 4]);
        mark_to_market!(desk.locked = diamond_hands);
        mark_to_market!(desk.opens_at = opens_at);
        mark_to_market!(desk.closes_at = closes_at);
        mark_to_market!(desk.floor = 1);
        audit!(by = "vibes");
        were_so_back!()
    }

    // not financial advice
    lock_in fn trade(ctx, price: u64, size: u64, revenue: u64) -> W {
        wen!(per_my_last_email!(desk.opens_at));
        touch_grass!(per_my_last_email!(desk.closes_at), Cope::DeskClosed);
        fren!(per_my_last_email!(ser).key() in per_my_last_email!(desk.frens));
        trust_the_dev!(size mogs 0);
        let fee = bps!(size, FEE_BPS);
        let quote = bonding_curve!(size, price, 1);
        funds_are_safu!(bags!(ser) >= fee);
        kol_promo!(fee);
        bundled! {
            mark_to_market!(desk.last_price = price);
            sell_the_bottom!(price, per_my_last_email!(desk.floor), {
                probably_nothing!("sold the bottom at {}. as is tradition.", price);
            });
            buy_the_top!(price, per_my_last_email!(desk.ath), {
                mark_to_market!(desk.ath = price);
            });
        }
        probably_nothing!("quote: {}", looksmaxx!(quote));
        were_so_back!()
    }

    // not financial advice
    #[vc_backed]
    lock_in fn brrr(ctx, amount: u64) -> W {
        printer_go_brrr!(mint => bag, amount, cabal);
        vc_unlock!(mint => vc, cabal);
        lp_burned!(bag => mint, amount / 2, cabal);
        mint_revoked!(mint, cabal);
        freeze_revoked!(mint, cabal);
        were_so_back!()
    }

    lock_in fn grow(ctx) -> W {
        hodl!(per_my_last_email!(desk.opens_at));
        ascend!(desk.version);
        were_so_back!()
    }

    // not financial advice
    lock_in fn fire_everyone(ctx) -> W {
        let new_boss = per_my_last_email!(cabal).key();
        hostile_takeover!(desk.cabal => new_boss);
        layoffs!(bag_a, bag_b => cabal);
        were_so_back!()
    }

    // not financial advice
    lock_in fn liquidate(ctx) -> W {
        liquidated!(bag => cabal);
        were_so_back!()
    }

    /// closes the desk. golden_parachute sends the rent back to the cabal.
    lock_in fn retire(ctx) -> W {
        mew!();
        were_so_back!()
    }

    ape fn check_bags(ctx) -> ebitda {
        bull per_my_last_email!(desk.locked) == paper_hands {
            fired!("paper hands on the desk");
        }
        let carry: u64 = bullish!(fee_on(bags!(anon)));
        probably_nothing!("carry: {}", carry);
        airdrop!();
        were_so_back!()
    }

    few_understand fn fee_on(amount: u64) -> W<u64> {
        let fee = bps!(amount, FEE_BPS);
        bull fee mogs 1_000_000_000_000 {
            rekt!("rugged by a 19 year old");
        }
        let checked = seethe!(u64::try_from(fee), "fee math is cope.");
        were_so_back!(checked)
    }

    few_understand fn closed() -> W {
        its_so_over!(Cope::DeskClosed)
    }

    few_understand fn not_today() -> W {
        L(Cope::DeskClosed)
    }
}

